<div class="shift-close-backdrop" id="shift-close-backdrop" hidden></div><aside class="shift-close-drawer" id="shift-close-drawer" role="dialog" aria-modal="true" aria-labelledby="shift-close-title" hidden><header class="shift-drawer-head"><div><h2 id="shift-close-title">Close shift</h2><p id="shift-close-meta" class="panel-sub mb-0"></p></div><button type="button" class="icon-action" data-close-shift-drawer aria-label="Close form">×</button></header><form method="post" id="shift-close-form" data-url-template="{{ route('shifts.close',['shift'=>'__SHIFT__']) }}">@csrf<div id="shift-close-readings"></div><div class="row g-3 mt-1">@foreach(['cash_collected'=>'Cash','upi_collected'=>'UPI','bank_collected'=>'Bank','card_collected'=>'Card','credit_sales'=>'Credit sales'] as $key=>$label)<div class="col-6"><label class="form-label" for="{{ $key }}">{{ $label }} (₹)</label><input id="{{ $key }}" class="form-control" type="number" name="{{ $key }}" min="0" step="0.01" value="0" required></div>@endforeach</div><div class="mt-3"><label class="form-label" for="shift-close-remarks">Closing remarks</label><textarea id="shift-close-remarks" class="form-control" name="remarks" rows="3" maxlength="2000"></textarea></div><footer class="shift-drawer-actions"><button type="button" class="btn btn-light" data-close-shift-drawer>Cancel</button><button type="submit" class="btn btn-primary">Submit shift</button></footer></form></aside>
<script>(()=>{const backdrop=document.getElementById('shift-close-backdrop'),drawer=document.getElementById('shift-close-drawer'),form=document.getElementById('shift-close-form'),meta=document.getElementById('shift-close-meta'),fields=document.getElementById('shift-close-readings');if(!backdrop||!drawer||!form)return;const close=()=>{backdrop.hidden=true;drawer.hidden=true;document.body.classList.remove('shift-drawer-open')};document.addEventListener('click',event=>{const trigger=event.target.closest('[data-close-shift]');if(trigger){let readings=[];try{readings=JSON.parse(trigger.dataset.readings||'[]')}catch{}fields.replaceChildren();for(const reading of readings){const group=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input'),opening=Number(reading.opening)||0;group.className='mb-3';label.className='form-label';label.textContent=`${reading.name} closing · opening ${opening.toFixed(3)}`;input.className='form-control';input.type='number';input.name=`readings[${reading.id}][closing]`;input.min=String(opening);input.step='0.001';input.required=true;group.append(label,input);fields.append(group)}meta.textContent=trigger.dataset.shiftLabel||'';form.action=form.dataset.urlTemplate.replace('__SHIFT__',encodeURIComponent(trigger.dataset.shiftId));backdrop.hidden=false;drawer.hidden=false;document.body.classList.add('shift-drawer-open');fields.querySelector('input')?.focus();return}if(event.target===backdrop||event.target.closest('[data-close-shift-drawer]'))close()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!drawer.hidden)close()})})();</script>
