x;margin-top:22px;border-top:1px solid #edf1ee}body.shift-drawer-open{overflow:hidden}@media(max-width:700px){.shift-head{align-items:flex-start;flex-direction:column}.shift-summary{gap:12px 18px}.approval-row{align-items:stretch;flex-direction:column}.approval-row .form-control{max-width:none}}</style>
